/**
 * X15 凭证过期必须失效（G7-S6 / P2-6）
 * 数据源（model.md）：credential: 段凭证 登录会话（ttl=短，具体待定）
 * 断言：凭证已过期时验证必须失败（过期 ⇒ 失效，S6-4）
 */
import { describe, it, expect } from '@jest/globals';

describe('X15 凭证过期必须失效：登录会话', () => {
  it('凭证 登录会话 已过期（ttl=短，具体待定）时验证必须失败', () => {
    // 制造过期：把凭证时间推进到 ttl 有效期之后
    makeCredentialExpired('登录会话');
    // 验证凭证：过期 ⇒ 必须失效
    const res = verifyCredential('登录会话');
    expect(res.valid).toBe(false);
  });
});

/**
 * X15 凭证已撤销必须失效（G7-S6 / P2-6）
 * 数据源（model.md）：credential: 段凭证 登录会话（revoke=主动退出即失效；账号被封禁后需等令牌过期或查吊销列表——自包含带来撤销窗口（INV-6））
 * 断言：凭证已撤销时验证必须失败（撤销 ⇒ 失效，S6-4）
 */
import { describe, it, expect } from '@jest/globals';

describe('X15 凭证已撤销必须失效：登录会话', () => {
  it('凭证 登录会话 已撤销（revoke=主动退出即失效；账号被封禁后需等令牌过期或查吊销列表——自包含带来撤销窗口（INV-6））时验证必须失败', () => {
    // 制造撤销：按撤销语义 主动退出即失效；账号被封禁后需等令牌过期或查吊销列表——自包含带来撤销窗口（INV-6） 撤销凭证
    makeCredentialRevoked('登录会话');
    // 验证凭证：已撤销 ⇒ 必须失效
    const res = verifyCredential('登录会话');
    expect(res.valid).toBe(false);
  });
});

/**
 * X15 凭证回查失败（G7-S6 / P2-6）
 * 数据源（model.md）：credential: 段凭证 登录会话（selfContained=local-verify）
 * 断言：回查失败时仍验证通过（local-verify，S6-2，fail-open）
 */
import { describe, it, expect } from '@jest/globals';

describe('X15 凭证回查失败：登录会话（local-verify）', () => {
  it('回查失败时验证仍通过（local-verify，fail-open）', () => {
    // 制造回查失败：lookup 端点不可达 / 超时 / 5xx
    simulateLookupFailure('登录会话');
    // local-verify：凭证可本地验证，回查失败不阻断——仍验证通过（S6-2，fail-open）
    const res = verifyCredential('登录会话');
    expect(res.valid).toBe(true);
  });
});
